 91	 * @param slug       - Project slug (e.g. `2026-05-05-my-feature`).
 92	 * @returns An object with two fields:
 93	 *   - `exists` — `true` when `<ledgerRoot>/<slug>/project-ledger.json` is present and
 94	 *     readable; `false` on any I/O error or when the file does not exist.
 95	 *   - `synthesisGenerated` — `true` when the ledger's `synthesis_generated` field equals
 96	 *     `true`; `false` when the file is absent, unreadable, or the field is falsy.
 97	 */
 98	export async function getProjectLedgerStatus(
 99	  ledgerRoot: string,
100	  slug: string,

101	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
102	  const projectLedgerPath = join(ledgerRoot, slug, 'project-ledger.json');
103	  let raw: string;
104	  try {
105	    raw = await readFile(projectLedgerPath, 'utf-8');
106	  } catch {
107	    return { exists: false, synthesisGenerated: false };
108	  }
109	  try {
110	    const data = JSON.parse(raw) as Record<string, unknown>;
111	    return {
112	      exists: true,
113	      synthesisGenerated: data['synthesis_generated'] === true,
114	    };
115	  } catch {
116	    return { exists: true, synthesisGenerated: false };
117	  }
118	}
