124	/**
125	 * Reads the shared orchestrator run queue and returns all active entries
126	 * enriched with computed lifecycle state and JSONL progress summaries.
127	 *
128	 * Entries for completed projects (`synthesis_generated === true`) are
129	 * automatically excluded from the result.
130	 *
131	 * This function is read-only: it never writes to the queue file or any
132	 * other file on disk.
133	 *
134	 * @param params.logsDir    - Absolute path to `orchestrator/logs/`.
135	 * @param params.ledgerRoot - Absolute path to the central ledger root.
136	 * @returns Enriched queue entries, excluding completed runs.
137	 */
138	export async function getQueue(params: {
139	  logsDir: string;
140	  ledgerRoot: string;
141	}): Promise<QueueEntry[]> {
142	  const { logsDir, ledgerRoot } = params;
143	
144	  const rawEntries = await readQueueFile(logsDir);
145	  if (rawEntries.length === 0) return [];
146	
147	  const enriched = await Promise.all(
148	    rawEntries.map(async (entry) => {
149	      const [projectStatus, progressResult] = await Promise.all([
150	        getProjectLedgerStatus(ledgerRoot, entry.expectedSlug),
151	        resolveProgress(logsDir, entry.expectedSlug),
152	      ]);
153	
154	      const { exists: projectExists, synthesisGenerated } = projectStatus;
155	      const alive = isProcessAlive(entry.pid);
156	
157	      // Compute effective status per AC-2 through AC-5.
158	      const effectiveStatus = computeEffectiveStatus(alive, projectExists, progressResult.hasStageActivity);
159	
160	      // AC-6: exclude entries whose project has completed synthesis.
161	      if (effectiveStatus === 'started' && synthesisGenerated) {
162	        return null;
163	      }
164	
165	      const result: QueueEntry = {
166	        ...entry,
167	        effectiveStatus,
168	        progress:      progressResult.summary,
169	        lastAction:    progressResult.lastAction,
170	        logFilename:   progressResult.logFilename,
171	        projectExists,
172	      };
173	      return result;
174	    }),
175	  );
176	
177	  return enriched.filter((e): e is QueueEntry => e !== null);
178	}

